const uint lane = thread_index_in_simdgroup;
const uint row0 = (threadgroup_position_in_grid.x * 8 + simdgroup_index_in_threadgroup) * 4;
float acc[4] = {0.f, 0.f, 0.f, 0.f};
for (int k0 = lane * 16; k0 < K; k0 += 512) {
    // x pre-scaled by 16^-i so nibbles can be masked in place (no shifts)
    float xp[16];
    float xs = 0.f;
    float sc = 1.f;
    for (int j = 0; j < 2; j++) {
        sc = 1.f;
        for (int i = 0; i < 8; i++) {
            float v = float(x[k0 + j * 8 + i]);
            xs += v;
            xp[j * 8 + i] = v * sc;
            sc *= 0.0625f;
        }
    }
    const int g = k0 >> 6;
    for (int r = 0; r < 4; r++) {
        uint n = row0 + r;
        if (n >= (uint)N) n = N - 1;  // clamp; result discarded
        uint2 w = ld2(wq + n * (K / 8) + (k0 >> 3));
        float s = float(scales[n * (K / 64) + g]);
        float b = float(biases[n * (K / 64) + g]);
        float d = 0.f;
        for (int i = 0; i < 8; i++) {
            d += xp[i] * float(w.x & (0xFu << (4 * i)));
            d += xp[8 + i] * float(w.y & (0xFu << (4 * i)));
        }
        acc[r] += s * d + b * xs;
    }
}
for (int r = 0; r < 4; r++) {
    float t = simd_sum(acc[r]);
    if (lane == 0 && row0 + r < (uint)N) out[row0 + r] = half(t);
}
